<script setup>
import {computed} from 'vue'
const props=defineProps({mode:String,state:Object,parameters:Object})
const title=computed(()=>({plasma:'Current balance of isolated suit',tribo:'Contact, separation and internal electrodes',harvester:'Energy path and electrical reference nodes',emitter:'Electron emission and return',discharge:'Current-limited equalization at lander'}[props.mode]))
const current=computed(()=>((props.state?.landerCurrent||props.state?.plasmaCurrent||props.state?.emitterCurrent||0)*1e6).toFixed(3))
const offset=computed(()=>-(props.state?.time||0)*16)
const external=computed(()=>props.parameters.harvester==='plasma')
</script>
<template><section class="bench-diagram"><header><span class="eyebrow">FUNCTIONAL VIEW</span><h2>{{title}}</h2></header><svg viewBox="0 0 780 260" role="img" :aria-label="title"><defs><linearGradient id="lcc-metal" x2="0" y2="1"><stop stop-color="#d8e6eb"/><stop offset=".45" stop-color="#f7fafc"/><stop offset="1" stop-color="#a0b8c7"/></linearGradient></defs>
<template v-if="mode==='tribo'||mode==='harvester'&&parameters.harvester==='tribo'"><path d="M140 175L480 175L530 204L115 204Z" fill="#b5bec4"/><path d="M140 179L480 179" stroke="#566b79" stroke-width="5"/><rect x="160" y="80" width="310" height="70" rx="18" fill="url(#lcc-metal)"/><g v-for="(color,i) in ['#b2c1ce','#233e52','#b88a44','#5b7687']" :key="i"><rect x="155" :y="148+i*9" width="325" height="8" :fill="color"/></g><path d="M480 164H580V110H660" fill="none" stroke="#167c80" stroke-width="3"/><rect x="570" y="62" width="136" height="48" rx="4" fill="#e1f0ef" stroke="#167c80"/><text x="638" y="91" text-anchor="middle">Internal generator</text><text x="580" y="155">{{state?.steps||0}} Contacts</text><text x="580" y="182">External Q: {{((state?.charge||0)*1e6).toFixed(3)}} µC</text><text x="160" y="239">Regolith · Material factors are model assumptions</text></template>
<template v-else-if="mode==='plasma'"><rect x="290" y="42" width="200" height="170" rx="28" fill="url(#lcc-metal)" stroke="#8ba5b8"/><path d="M330 75H450M330 84H450M330 175H450M330 184H450" stroke="#167c80" stroke-width="3"/><text x="390" y="126" text-anchor="middle">C · V = Q</text><text x="390" y="151" text-anchor="middle">{{((state?.voltage||0)/1000).toFixed(2)}} kV</text><g v-for="i in 5" :key="i"><path :d="`M80 ${60+i*24}H275`" stroke="#2563a9" stroke-width="2" stroke-dasharray="5 8" :stroke-dashoffset="offset"/></g><path d="M505 80H705M505 150H705" stroke="#ce8538" stroke-width="3" stroke-dasharray="7 10" :stroke-dashoffset="-offset"/><text x="80" y="40">Electrons (−)</text><text x="535" y="65">Ions (+)</text><text x="535" y="135">Photoemission (+)</text><text x="290" y="244">Net: {{current}} µA · {{state?.shadow?'without illumination':'with illumination'}}</text></template>
<template v-else-if="mode==='emitter'"><rect x="70" y="65" width="145" height="135" rx="18" fill="url(#lcc-metal)"/><text x="143" y="125" text-anchor="middle">Suit</text><text x="143" y="151" text-anchor="middle">{{((state?.voltage||0)/1000).toFixed(2)}} kV</text><path d="M215 125H335" stroke="#167c80" stroke-width="4"/><rect x="335" y="83" width="132" height="84" rx="4" fill="#e1f0ef" stroke="#167c80"/><text x="401" y="116" text-anchor="middle">Emitter</text><text x="401" y="143" text-anchor="middle">{{state?.emitterOn?'active':'inactive'}}</text><path d="M470 110H715" stroke="#2563a9" stroke-width="3" stroke-dasharray="5 10" :stroke-dashoffset="state?.emitterOn?offset:0"/><path d="M640 172Q545 235 467 156" fill="none" stroke="#b78a4d" stroke-width="2" stroke-dasharray="4 7"/><text x="510" y="83">Escaping: {{(parameters.escapeFraction*100).toFixed(0)}} %</text><text x="490" y="230">Returning electrons: no net transfer</text><text x="70" y="239">Electrical power supplied by storage</text></template>
<template v-else><rect x="55" y="65" width="145" height="132" rx="12" fill="url(#lcc-metal)"/><text x="127" y="112" text-anchor="middle">{{mode==='discharge'?'Suit':'Energy source'}}</text><text x="127" y="142" text-anchor="middle">{{((mode==='discharge'?state?.voltage:state?.inputVoltage)||0).toFixed(1)}} V</text><path d="M200 125H295M485 125H580" stroke="#167c80" stroke-width="3" stroke-dasharray="7 6" :stroke-dashoffset="offset"/><rect x="295" y="81" width="190" height="88" rx="5" fill="#e1f0ef" stroke="#167c80"/><text x="390" y="116" text-anchor="middle">{{mode==='discharge'?'R + Current limit':parameters.harvester==='capacitive'?'Capacitive sharing':'Converter'}}</text><text x="390" y="143" text-anchor="middle">{{mode==='discharge'?current+' µA':(parameters.efficiency*100).toFixed(0)+' % Efficiency'}}</text><rect x="580" y="66" width="145" height="132" rx="8" fill="#dce9f2" stroke="#8ba5b8"/><text x="652" y="115" text-anchor="middle">{{mode==='discharge'?'Lander':'Storage'}}</text><text x="652" y="145" text-anchor="middle">{{mode==='discharge'?parameters.landerVoltage+' V':(state?.storage||0).toFixed(4)+' J'}}</text><path d="M650 198V226H125V198" stroke="#9b7e55" stroke-width="2" fill="none" :stroke-dasharray="mode==='harvester'&&!external?'4 5':undefined"/><text x="390" y="250" text-anchor="middle">{{mode==='discharge'?'Second reference node: lander':external?'Second reference node: plasma collector':'Closed internal circuit · external net charge is conserved'}}</text></template>
</svg></section></template>
